"""Shared helpers for the minisql test suite."""

import csv
import io
import os
import subprocess
import sys
import tempfile
import unittest

PROJECT_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if PROJECT_ROOT not in sys.path:
    sys.path.insert(0, PROJECT_ROOT)

import minisql


def write_table(directory, name, header, rows):
    """Write ``header`` and ``rows`` to ``name.csv`` in ``directory``."""
    filename = name if name.endswith(".csv") else name + ".csv"
    path = os.path.join(directory, filename)
    with open(path, "w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(header)
        writer.writerows(rows)


def write_raw(directory, name, text):
    """Write raw CSV text to ``name.csv`` in ``directory``."""
    filename = name if name.endswith(".csv") else name + ".csv"
    with open(os.path.join(directory, filename), "w", newline="", encoding="utf-8") as handle:
        handle.write(text)


class MinisqlTestCase(unittest.TestCase):
    """Base class providing a temporary data directory and query helpers."""

    def setUp(self):
        self._tmpdir = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmpdir.cleanup)
        self.directory = self._tmpdir.name

    def make_table(self, name, header, rows):
        write_table(self.directory, name, header, rows)

    def query(self, sql, directory=None):
        if directory is None:
            directory = self.directory
        return minisql.run(sql, directory)

    def columns(self, sql):
        return self.query(sql).columns

    def rows(self, sql):
        return self.query(sql).rows

    def assertRows(self, sql, expected):
        expected = [tuple(row) for row in expected]
        self.assertEqual(self.rows(sql), expected)

    def assertColumns(self, sql, expected):
        self.assertEqual(self.columns(sql), list(expected))

    def assertScalar(self, sql, expected):
        result = self.query(sql)
        self.assertEqual(len(result.columns), 1, result.columns)
        self.assertEqual(len(result.rows), 1, result.rows)
        self.assertEqual(result.rows[0], (expected,))
        return result.rows[0][0]

    def assertQueryError(self, sql, directory=None):
        with self.assertRaises(minisql.QueryError):
            self.query(sql, directory=directory)


def run_cli(args, cwd=None):
    """Run ``python -m minisql`` with the given arguments."""
    env = os.environ.copy()
    existing = env.get("PYTHONPATH")
    env["PYTHONPATH"] = PROJECT_ROOT + (os.pathsep + existing if existing else "")
    return subprocess.run(
        [sys.executable, "-m", "minisql"] + list(args),
        cwd=cwd or PROJECT_ROOT,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        env=env,
    )


def stdout_of(process):
    return process.stdout.decode("utf-8")


def stderr_of(process):
    return process.stderr.decode("utf-8", "replace")


def parse_csv(text):
    return list(csv.reader(io.StringIO(text, newline="")))

"""Tests for expression semantics: NULL, arithmetic, comparison, IN, LIKE."""

import unittest

from _util import MinisqlTestCase


class ExpressionTestCase(MinisqlTestCase):
    def setUp(self):
        super().setUp()
        self.make_table("one", ["x"], [["1"]])


class NullTests(ExpressionTestCase):
    def test_null_propagates_through_operators_and_functions(self):
        sql = (
            "SELECT NULL, 1 + NULL, 'a' || NULL, NULL = 1, NULL AND TRUE, "
            "NULL OR FALSE, NOT NULL, LOWER(NULL), UPPER(NULL), LENGTH(NULL), "
            "ABS(NULL), ROUND(NULL), COALESCE(NULL, NULL) FROM one"
        )
        self.assertRows(sql, [(None,) * 13])

    def test_null_is_not_the_empty_string(self):
        self.assertRows("SELECT '' IS NULL, '' = NULL FROM one", [(False, None)])

    def test_null_result_columns_keep_their_names(self):
        result = self.query("SELECT NULL AS n FROM one")
        self.assertEqual(result.columns, ["n"])
        self.assertEqual(result.rows, [(None,)])


class ThreeValuedLogicTests(ExpressionTestCase):
    def test_and_truth_table(self):
        self.assertRows(
            "SELECT TRUE AND TRUE, TRUE AND FALSE, TRUE AND NULL, "
            "FALSE AND FALSE, FALSE AND NULL, NULL AND NULL FROM one",
            [(True, False, None, False, False, None)],
        )

    def test_or_truth_table(self):
        self.assertRows(
            "SELECT TRUE OR TRUE, TRUE OR FALSE, TRUE OR NULL, "
            "FALSE OR FALSE, FALSE OR NULL, NULL OR NULL FROM one",
            [(True, True, True, False, None, None)],
        )

    def test_not_truth_table(self):
        self.assertRows(
            "SELECT NOT TRUE, NOT FALSE, NOT NULL FROM one",
            [(False, True, None)],
        )

    def test_boolean_results_are_bools(self):
        rows = self.rows(
            "SELECT TRUE, FALSE, 1 = 1, NULL IS NULL, TRUE AND NULL FROM one"
        )
        (values,) = rows
        for value in values[:4]:
            self.assertIs(type(value), bool)
        self.assertIsNone(values[4])

    def test_where_keeps_only_true(self):
        self.make_table("t", ["v"], [["1"], ["2"], [""]])
        self.assertEqual(self.rows("SELECT v FROM t WHERE NULL"), [])
        self.assertEqual(self.rows("SELECT v FROM t WHERE TRUE"), [(1,), (2,), (None,)])
        self.assertEqual(self.rows("SELECT v FROM t WHERE FALSE"), [])
        self.assertEqual(self.rows("SELECT v FROM t WHERE v > 1"), [(2,)])

    def test_where_not_null_removes_all_rows(self):
        self.make_table("t", ["v"], [["1"]])
        self.assertEqual(self.rows("SELECT v FROM t WHERE NOT NULL"), [])


class ArithmeticTests(ExpressionTestCase):
    def test_integer_arithmetic_stays_integer(self):
        result = self.query("SELECT 1 + 2, 5 - 3, 4 * 3, -2 * 3 FROM one")
        self.assertEqual(result.rows, [(3, 2, 12, -6)])
        for value in result.rows[0]:
            self.assertIs(type(value), int)

    def test_true_division_always_returns_float(self):
        result = self.query("SELECT 7 / 2, 4 / 2, 1 / 4 FROM one")
        self.assertEqual(result.rows, [(3.5, 2.0, 0.25)])
        for value in result.rows[0]:
            self.assertIs(type(value), float)

    def test_mixed_arithmetic_returns_float(self):
        result = self.query("SELECT 1.5 + 2, 2 * 2.5, 5 - 1.5, 2 + 2.0 FROM one")
        self.assertEqual(result.rows, [(3.5, 5.0, 3.5, 4.0)])
        for value in result.rows[0]:
            self.assertIs(type(value), float)

    def test_division_by_zero_is_null(self):
        self.assertRows(
            "SELECT 1 / 0, 0 / 0, 1.0 / 0, -3 / 0 FROM one",
            [(None, None, None, None)],
        )

    def test_null_propagation_in_arithmetic(self):
        self.assertRows(
            "SELECT 1 + 1 / 0, 1 / 0 * 5, 1 / 0 + 1 / 0 FROM one",
            [(None, None, None)],
        )

    def test_unary_minus(self):
        result = self.query("SELECT -5, -2.5, - -3, -x FROM one")
        self.assertEqual(result.rows, [(-5, -2.5, 3, -1)])
        self.assertIs(type(result.rows[0][0]), int)
        self.assertIs(type(result.rows[0][1]), float)
        self.assertIs(type(result.rows[0][2]), int)
        self.assertIs(type(result.rows[0][3]), int)

    def test_arithmetic_on_strings_is_an_error(self):
        for sql in [
            "SELECT 'a' + 1 FROM one",
            "SELECT 1 + 'a' FROM one",
            "SELECT 'a' * 2 FROM one",
            "SELECT 'a' / 2 FROM one",
            "SELECT -'a' FROM one",
        ]:
            with self.subTest(sql=sql):
                self.assertQueryError(sql)

    def test_arithmetic_on_booleans_is_an_error(self):
        for sql in [
            "SELECT TRUE + 1 FROM one",
            "SELECT 1 - FALSE FROM one",
            "SELECT TRUE * TRUE FROM one",
            "SELECT -TRUE FROM one",
        ]:
            with self.subTest(sql=sql):
                self.assertQueryError(sql)


class ConcatenationTests(ExpressionTestCase):
    def test_concatenation_uses_text_of_operands(self):
        self.assertRows(
            "SELECT 'a' || 'b', 'a' || 1, 1 || 2, 1.5 || 'x', 2.0 || '', "
            "'' || '' FROM one",
            [("ab", "a1", "12", "1.5x", "2.0", "")],
        )

    def test_concatenating_booleans_uses_lowercase(self):
        self.assertRows(
            "SELECT TRUE || '!', FALSE || '!' FROM one",
            [("true!", "false!")],
        )

    def test_concatenation_with_null_is_null(self):
        self.assertRows(
            "SELECT 'x' || NULL, NULL || 'x', NULL || NULL FROM one",
            [(None, None, None)],
        )

    def test_concatenation_has_addition_precedence_left_to_right(self):
        self.assertRows("SELECT 1 + 2 || 'x' FROM one", [("3x",)])
        # + and || share a precedence level and are left-associative, so this
        # parses as ('a' || 1) + 2 and is an arithmetic error.
        self.assertQueryError("SELECT 'a' || 1 + 2 FROM one")


class ComparisonTests(ExpressionTestCase):
    def test_numbers_compare_numerically(self):
        self.assertRows(
            "SELECT 1 = 1.0, 1 != 1.0, 1 <> 2, 2 < 10, 10 >= 10, "
            "1.5 > 1, -1 < 0, 1.0 = 1 FROM one",
            [(True, False, True, True, True, True, True, True)],
        )

    def test_strings_compare_by_code_point(self):
        self.assertRows(
            "SELECT 'abc' = 'abc', 'a' < 'b', 'Z' < 'a', '2' < '10', "
            "'' < 'a', 'abc' != 'abd' FROM one",
            [(True, True, True, False, True, True)],
        )

    def test_booleans_compare_with_booleans(self):
        self.assertRows(
            "SELECT TRUE = TRUE, FALSE = FALSE, TRUE <> FALSE, "
            "TRUE = FALSE FROM one",
            [(True, True, True, False)],
        )

    def test_comparison_with_null_is_null(self):
        self.assertRows(
            "SELECT NULL = NULL, NULL != 1, NULL < 1, 1 <= NULL, "
            "NULL > NULL FROM one",
            [(None, None, None, None, None)],
        )

    def test_comparison_results_are_bools(self):
        (values,) = self.rows("SELECT 1 = 1, 1 < 2, TRUE = TRUE FROM one")
        for value in values:
            self.assertIs(type(value), bool)

    def test_comparing_number_with_string_is_an_error(self):
        for sql in [
            "SELECT 1 = '1' FROM one",
            "SELECT '1' = 1 FROM one",
            "SELECT 1 < '1' FROM one",
            "SELECT 'a' > 1 FROM one",
        ]:
            with self.subTest(sql=sql):
                self.assertQueryError(sql)

    def test_comparing_boolean_with_number_is_an_error(self):
        for sql in [
            "SELECT TRUE = 1 FROM one",
            "SELECT 0 = FALSE FROM one",
            "SELECT TRUE < 2 FROM one",
        ]:
            with self.subTest(sql=sql):
                self.assertQueryError(sql)

    def test_comparison_type_error_inside_where(self):
        self.make_table("t", ["v"], [["1"]])
        self.assertQueryError("SELECT v FROM t WHERE v = '1'")


class InListTests(ExpressionTestCase):
    def test_in_list_truth_values(self):
        self.assertRows(
            "SELECT 1 IN (1, 2), 3 IN (1, 2), 1 IN (1, NULL), "
            "2 IN (1, NULL), NULL IN (1, 2) FROM one",
            [(True, False, True, None, None)],
        )

    def test_not_in_truth_values(self):
        self.assertRows(
            "SELECT 1 NOT IN (1, NULL), 2 NOT IN (1, NULL), "
            "3 NOT IN (1, 2), NULL NOT IN (1, 2) FROM one",
            [(False, None, True, None)],
        )

    def test_in_with_strings_and_expressions(self):
        self.assertRows(
            "SELECT 'a' IN ('a', 'b'), 'c' NOT IN ('a', 'b'), "
            "2 IN (1 + 1, 5) FROM one",
            [(True, True, True)],
        )

    def test_in_filters_rows(self):
        self.make_table("t", ["v"], [["1"], ["2"], ["3"]])
        self.assertEqual(self.rows("SELECT v FROM t WHERE v IN (1, 3)"), [(1,), (3,)])
        self.assertEqual(self.rows("SELECT v FROM t WHERE v NOT IN (1, 3)"), [(2,)])

    def test_not_in_with_null_excludes_null_rows(self):
        self.make_table("t", ["v"], [["1"], ["2"], [""]])
        self.assertEqual(self.rows("SELECT v FROM t WHERE v NOT IN (1)"), [(2,)])


class BetweenTests(ExpressionTestCase):
    def test_between_is_inclusive(self):
        self.assertRows(
            "SELECT 5 BETWEEN 1 AND 10, 1 BETWEEN 1 AND 10, "
            "10 BETWEEN 1 AND 10, 0 BETWEEN 1 AND 10, "
            "11 BETWEEN 1 AND 10 FROM one",
            [(True, True, True, False, False)],
        )

    def test_not_between(self):
        self.assertRows(
            "SELECT 5 NOT BETWEEN 1 AND 10, 0 NOT BETWEEN 1 AND 10, "
            "5 NOT BETWEEN 5 AND 5 FROM one",
            [(False, True, False)],
        )

    def test_between_with_null_is_null(self):
        self.assertRows(
            "SELECT 5 BETWEEN NULL AND 10, 5 BETWEEN 1 AND NULL, "
            "NULL BETWEEN 1 AND 10, 5 NOT BETWEEN NULL AND 10 FROM one",
            [(None, None, None, None)],
        )

    def test_between_with_reversed_bounds_is_false(self):
        self.assertRows("SELECT 5 BETWEEN 10 AND 1 FROM one", [(False,)])
        self.assertRows("SELECT 5 BETWEEN 1 AND 2 FROM one", [(False,)])

    def test_between_with_strings(self):
        self.assertRows(
            "SELECT 'b' BETWEEN 'a' AND 'c', 'd' BETWEEN 'a' AND 'c' FROM one",
            [(True, False)],
        )

    def test_between_filters_rows(self):
        self.make_table("t", ["v"], [["1"], ["2"], ["3"]])
        self.assertEqual(
            self.rows("SELECT v FROM t WHERE v BETWEEN 2 AND 3"), [(2,), (3,)]
        )

    def test_between_high_bound_then_and(self):
        self.make_table("t", ["v"], [["1"]])
        self.assertEqual(
            self.rows("SELECT v FROM t WHERE v BETWEEN 1 AND 2 AND v = 1"),
            [(1,)],
        )


class LikeTests(ExpressionTestCase):
    def test_like_matches_whole_string(self):
        self.assertRows(
            "SELECT 'abc' LIKE 'a%', 'abc' LIKE '%b%', 'abc' LIKE 'abc', "
            "'abc' LIKE 'a_', 'abc' LIKE '___', 'abc' LIKE 'A%', "
            "'abc' LIKE 'a.c', 'a.c' LIKE 'a.c', 'abc' LIKE 'ab' FROM one",
            [
                (
                    True,
                    True,
                    True,
                    False,
                    True,
                    False,
                    False,
                    True,
                    False,
                )
            ],
        )

    def test_like_wildcards_and_empty_string(self):
        self.assertRows(
            "SELECT '' LIKE '%', '' LIKE '_', 'a' LIKE '_', 'ab' LIKE '__', "
            "'abc' LIKE '%c', '%' LIKE '%' FROM one",
            [(True, False, True, True, True, True)],
        )

    def test_like_is_case_sensitive(self):
        self.assertRows(
            "SELECT 'abc' LIKE 'ABC', 'ABC' LIKE 'ABC' FROM one",
            [(False, True)],
        )

    def test_like_with_null_is_null(self):
        self.assertRows(
            "SELECT NULL LIKE '%', 'abc' LIKE NULL, NULL NOT LIKE '%' FROM one",
            [(None, None, None)],
        )

    def test_not_like(self):
        self.assertRows(
            "SELECT 'abc' NOT LIKE 'a%', 'abc' NOT LIKE 'x%' FROM one",
            [(False, True)],
        )

    def test_like_pattern_can_be_an_expression(self):
        self.assertRows("SELECT 'abc' LIKE 'a' || '%' FROM one", [(True,)])

    def test_like_filters_rows(self):
        self.make_table("t", ["v"], [["apple"], ["apricot"], ["banana"]])
        self.assertEqual(
            self.rows("SELECT v FROM t WHERE v LIKE 'ap%'"), [("apple",), ("apricot",)]
        )
        self.assertEqual(self.rows("SELECT v FROM t WHERE v NOT LIKE '%a%'"), [])


class IsNullTests(ExpressionTestCase):
    def test_is_null_and_is_not_null(self):
        self.assertRows(
            "SELECT NULL IS NULL, NULL IS NOT NULL, 1 IS NULL, "
            "1 IS NOT NULL, '' IS NULL, (1 / 0) IS NULL, "
            "(1 / 0) IS NOT NULL FROM one",
            [(True, False, False, True, False, True, False)],
        )

    def test_is_null_combined_with_not(self):
        self.assertRows(
            "SELECT NOT 1 IS NULL, NOT NULL IS NULL FROM one",
            [(True, False)],
        )

    def test_is_null_filters_rows(self):
        self.make_table("t", ["v"], [["1"], [""], ["2"]])
        self.assertEqual(self.rows("SELECT v FROM t WHERE v IS NULL"), [(None,)])
        self.assertEqual(self.rows("SELECT v FROM t WHERE v IS NOT NULL"), [(1,), (2,)])


class TruthinessTests(ExpressionTestCase):
    def test_non_boolean_where_is_an_error(self):
        self.make_table("t", ["v"], [["1"]])
        for sql in [
            "SELECT v FROM t WHERE 1",
            "SELECT v FROM t WHERE 'yes'",
            "SELECT v FROM t WHERE v",
            "SELECT v FROM t WHERE v + 1",
        ]:
            with self.subTest(sql=sql):
                self.assertQueryError(sql)

    def test_non_boolean_logic_is_an_error(self):
        for sql in [
            "SELECT NOT 1 FROM one",
            "SELECT 1 AND TRUE FROM one",
            "SELECT FALSE OR 0 FROM one",
            "SELECT 'a' AND 'b' FROM one",
        ]:
            with self.subTest(sql=sql):
                self.assertQueryError(sql)


