    unittest.main()

"""Tests for scalar functions (SPEC.md "Scalar functions")."""

import unittest

from _util import MinisqlTestCase


class ScalarFunctionTests(MinisqlTestCase):
    def setUp(self):
        super().setUp()
        self.make_table("one", ["x"], [["1"]])
        self.make_table(
            "f", ["s", "x"], [["AbC", "-4.5"], ["", "2.5"], ["x", ""]]
        )

    def test_lower_upper_length(self):
        self.assertRows(
            "SELECT LOWER('AbC'), UPPER('AbC'), LENGTH('abc'), LENGTH('') FROM one",
            [("abc", "ABC", 3, 0)],
        )

    def test_lower_upper_length_on_columns(self):
        self.assertEqual(
            self.rows("SELECT LOWER(s), UPPER(s), LENGTH(s) FROM f"),
            [("abc", "ABC", 3), ("", "", 0), ("x", "X", 1)],
        )

    def test_abs_preserves_numeric_type(self):
        result = self.query("SELECT ABS(-5), ABS(-2.5), ABS(5), ABS(0) FROM one")
        self.assertEqual(result.rows, [(5, 2.5, 5, 0)])
        self.assertIs(type(result.rows[0][0]), int)
        self.assertIs(type(result.rows[0][1]), float)
        self.assertIs(type(result.rows[0][2]), int)

    def test_round_to_integer_rounds_halves_away_from_zero(self):
        result = self.query(
            "SELECT ROUND(2.5), ROUND(-2.5), ROUND(2.4), ROUND(-2.4), ROUND(3) FROM one"
        )
        self.assertEqual(result.rows, [(3, -3, 2, -2, 3)])
        for value in result.rows[0]:
            self.assertIs(type(value), int)

    def test_round_to_decimal_places_returns_float(self):
        result = self.query(
            "SELECT ROUND(1.25, 1), ROUND(-1.25, 1), ROUND(2.5, 0), "
            "ROUND(1.234, 2) FROM one"
        )
        self.assertEqual(result.rows, [(1.3, -1.3, 3.0, 1.23)])
        for value in result.rows[0]:
            self.assertIs(type(value), float)

    def test_round_on_columns(self):
        self.assertEqual(
            self.rows("SELECT ABS(x), ROUND(x), ROUND(x, 1) FROM f"),
            [(4.5, -5, -4.5), (2.5, 3, 2.5), (None, None, None)],
        )

    def test_coalesce_returns_first_non_null(self):
        self.assertRows(
            "SELECT COALESCE(NULL, NULL, 3), COALESCE(1, 2), "
            "COALESCE(NULL, 'x'), COALESCE(NULL, NULL), "
            "COALESCE(NULL, NULL, 2.5) FROM one",
            [(3, 1, "x", None, 2.5)],
        )

    def test_coalesce_on_column(self):
        self.assertEqual(
            self.rows("SELECT COALESCE(x, 0) FROM f"), [(4.5,), (2.5,), (0,)]
        )

    def test_null_operands_give_null(self):
        self.assertRows(
            "SELECT LOWER(NULL), UPPER(NULL), LENGTH(NULL), ABS(NULL), "
            "ROUND(NULL), ROUND(NULL, 2) FROM one",
            [(None,) * 6],
        )

    def test_nested_function_calls(self):
        self.assertRows(
            "SELECT UPPER(LOWER('Ab')), ABS(-ABS(-3)), "
            "COALESCE(LOWER(NULL), UPPER('x')), ROUND(ABS(-2.6)) FROM one",
            [("AB", 3, "X", 3)],
        )

    def test_function_names_are_case_insensitive(self):
        self.assertRows(
            "SELECT lower('A'), UpPeR('a'), LeNgTh('abc'), aBs(-1), "
            "RoUnD(2.5), CoAlEsCe(NULL, 1) FROM one",
            [("a", "A", 3, 1, 3, 1)],
        )

    def test_unknown_function_is_an_error(self):
        for sql in [
            "SELECT FOO(1) FROM one",
            "SELECT NOPE() FROM one",
            "SELECT LOWERX('a') FROM one",
        ]:
            with self.subTest(sql=sql):
                self.assertQueryError(sql)

    def test_wrong_number_of_arguments_is_an_error(self):
        for sql in [
            "SELECT LOWER() FROM one",
            "SELECT LOWER('a', 'b') FROM one",
            "SELECT UPPER() FROM one",
            "SELECT UPPER('a', 'b') FROM one",
            "SELECT LENGTH() FROM one",
            "SELECT LENGTH('a', 'b') FROM one",
            "SELECT ABS() FROM one",
            "SELECT ABS(1, 2) FROM one",
            "SELECT ROUND() FROM one",
            "SELECT ROUND(1, 2, 3) FROM one",
        ]:
            with self.subTest(sql=sql):
                self.assertQueryError(sql)


