    unittest.main()

"""Tests for aggregates and grouping (SPEC.md "Aggregates" and "Grouping")."""

import unittest

from _util import MinisqlTestCase


class AggregateTestCase(MinisqlTestCase):
    def setUp(self):
        super().setUp()
        self.make_table(
            "sales",
            ["grp", "val"],
            [
                ["a", "1"],
                ["a", "3"],
                ["a", ""],
                ["b", "2"],
                ["b", ""],
                ["c", ""],
            ],
        )


class AggregateBasicsTests(AggregateTestCase):
    def test_aggregates_over_all_rows(self):
        result = self.query(
            "SELECT COUNT(*), COUNT(val), SUM(val), AVG(val), "
            "MIN(val), MAX(val) FROM sales"
        )
        self.assertEqual(result.rows, [(6, 3, 6, 2.0, 1, 3)])

    def test_aggregate_result_types(self):
        (values,) = self.rows(
            "SELECT COUNT(*), COUNT(val), SUM(val), AVG(val), "
            "MIN(val), MAX(val) FROM sales"
        )
        count_star, count_vals, total, average, minimum, maximum = values
        self.assertIs(type(count_star), int)
        self.assertIs(type(count_vals), int)
        self.assertIs(type(total), int)
        self.assertIs(type(average), float)
        self.assertIs(type(minimum), int)
        self.assertIs(type(maximum), int)

    def test_count_star_counts_rows_and_count_expr_skips_nulls(self):
        self.assertEqual(
            self.rows("SELECT COUNT(*), COUNT(val), COUNT(grp) FROM sales"),
            [(6, 3, 6)],
        )

    def test_min_max_work_on_strings(self):
        self.assertEqual(
            self.rows("SELECT MIN(grp), MAX(grp) FROM sales"),
            [("a", "c")],
        )

    def test_sum_of_integers_is_integer(self):
        result = self.query("SELECT SUM(val) FROM sales")
        self.assertEqual(result.rows, [(6,)])
        self.assertIs(type(result.rows[0][0]), int)

    def test_avg_is_always_float(self):
        self.make_table("t", ["v"], [["2"], ["4"]])
        result = self.query("SELECT AVG(v) FROM t")
        self.assertEqual(result.rows, [(3.0,)])
        self.assertIs(type(result.rows[0][0]), float)

    def test_mixed_number_sum_is_float(self):
        self.make_table("t", ["v"], [["1"], ["2.5"], [""]])
        result = self.query("SELECT SUM(v), AVG(v), MIN(v), MAX(v) FROM t")
        self.assertEqual(result.rows, [(3.5, 1.75, 1, 2.5)])
