"""Tests for operator precedence and associativity (SPEC.md "Expressions")."""

import unittest

from _util import MinisqlTestCase


class PrecedenceTests(MinisqlTestCase):
    def setUp(self):
        super().setUp()
        self.make_table("one", ["x"], [["1"]])

    def test_multiplication_before_addition(self):
        self.assertRows(
            "SELECT 1 + 2 * 3, 2 * 3 + 1, 2 + 3 * 4 - 5 FROM one",
            [(7, 7, 9)],
        )

    def test_parentheses_override_precedence(self):
        self.assertRows(
            "SELECT (1 + 2) * 3, (1 + 2) * (3 + 4) FROM one",
            [(9, 21)],
        )

    def test_addition_subtraction_are_left_associative(self):
        self.assertRows(
            "SELECT 10 - 3 - 2, 8 - 3 + 2 FROM one",
            [(5, 7)],
        )

    def test_division_is_left_associative(self):
        self.assertRows(
            "SELECT 20 / 5 / 2, 100 / 10 / 2 FROM one",
            [(2.0, 5.0)],
        )

    def test_unary_minus_precedence(self):
        self.assertRows(
            "SELECT -2 * 3, 2 * -3, 2 - -3, - -3 FROM one",
            [(-6, -6, 5, 3)],
        )

    def test_not_binds_tighter_than_and(self):
        self.assertRows(
            "SELECT NOT FALSE AND FALSE, NOT (FALSE AND FALSE) FROM one",
            [(False, True)],
        )

    def test_and_binds_tighter_than_or(self):
        self.assertRows(
            "SELECT TRUE OR FALSE AND FALSE, (TRUE OR FALSE) AND FALSE FROM one",
            [(True, False)],
        )

    def test_not_binds_looser_than_comparison(self):
        self.assertRows(
            "SELECT NOT 1 = 2, NOT 1 = 1 FROM one",
