class CliOutputTests(CliTestCase):
    def test_header_and_rows_are_written_as_csv(self):
        proc = self.invoke(
            "SELECT name, age FROM people ORDER BY name",
            "--dir",
            self.directory,
        )
        self.assertEqual(proc.returncode, 0, stderr_of(proc))
        self.assertEqual(stderr_of(proc), "")
        self.assertEqual(
            parse_csv(stdout_of(proc)),
            [["name", "age"], ["Alice", "30"], ["Bob", ""]],
        )

    def test_null_is_written_as_an_empty_field(self):
        proc = self.invoke(
            "SELECT NULL AS n, 1 AS one, 'x' AS s FROM people LIMIT 1",
            "--dir",
            self.directory,
        )
        self.assertEqual(proc.returncode, 0, stderr_of(proc))
        self.assertEqual(
            parse_csv(stdout_of(proc)),
            [["n", "one", "s"], ["", "1", "x"]],
        )

    def test_booleans_are_lowercase_true_and_false(self):
        proc = self.invoke(
            "SELECT TRUE AS t, FALSE AS f, 1 = 1 AS eq FROM people LIMIT 1",
            "--dir",
            self.directory,
        )
        self.assertEqual(proc.returncode, 0, stderr_of(proc))
        self.assertEqual(
            parse_csv(stdout_of(proc)),
            [["t", "f", "eq"], ["true", "false", "true"]],
        )

    def test_empty_string_is_an_empty_field(self):
        proc = self.invoke(
            "SELECT '' AS empty FROM people LIMIT 1", "--dir", self.directory
        )
        self.assertEqual(proc.returncode, 0, stderr_of(proc))
        self.assertEqual(parse_csv(stdout_of(proc)), [["empty"], [""]])

    def test_zero_rows_still_have_a_header(self):
        proc = self.invoke(
            "SELECT name FROM people WHERE FALSE", "--dir", self.directory
        )
        self.assertEqual(proc.returncode, 0, stderr_of(proc))
        self.assertEqual(parse_csv(stdout_of(proc)), [["name"]])

    def test_csv_quoting(self):
        proc = self.invoke(
            "SELECT 'a,b' AS comma, 'say \"hi\"' AS quote, "
            "'it''s' AS apostrophe FROM people LIMIT 1",
            "--dir",
            self.directory,
        )
        self.assertEqual(proc.returncode, 0, stderr_of(proc))
        self.assertEqual(
            parse_csv(stdout_of(proc)),
            [["comma", "quote", "apostrophe"], ["a,b", 'say "hi"', "it's"]],
        )
        text = stdout_of(proc)
        self.assertIn('"a,b"', text)
        self.assertIn('"say ""hi"""', text)

