class CliErrorTests(CliTestCase):
    def assertCliQueryError(self, *args):
        proc = self.invoke(*args)
        stderr = stderr_of(proc)
        self.assertEqual(proc.returncode, 1, stderr)
        self.assertEqual(proc.stdout, b"")
        self.assertNotEqual(stderr.strip(), "")
        self.assertNotIn("Traceback (most recent call last)", stderr)
        return proc

    def test_unknown_column_is_a_query_error(self):
        self.assertCliQueryError(
            "SELECT missing FROM people", "--dir", self.directory
        )

    def test_unknown_table_is_a_query_error(self):
        self.assertCliQueryError("SELECT * FROM absent", "--dir", self.directory)

    def test_syntax_error_is_a_query_error(self):
        self.assertCliQueryError("SELECT", "--dir", self.directory)

    def test_type_error_is_a_query_error(self):
        self.assertCliQueryError(
            "SELECT name + 1 FROM people", "--dir", self.directory
        )

    def test_division_by_zero_is_not_an_error(self):
        proc = self.invoke(
            "SELECT 1 / 0 AS v FROM people LIMIT 1", "--dir", self.directory
        )
        self.assertEqual(proc.returncode, 0, stderr_of(proc))
        self.assertEqual(parse_csv(stdout_of(proc)), [["v"], [""]])


